<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<title>Diario Official - Abril 1930</title>
<style>
    body {
        font-family: Georgia, 'Times New Roman', serif;
        background-color: #f0ede6;
        color: #1a1a1a;
        max-width: 1000px;
        margin: 0 auto;
        padding: 20px;
        font-size: 14px;
        line-height: 1.4;
    }
    .header {
        display: flex;
        justify-content: space-between;
        border-bottom: 2px solid #000;
        padding-bottom: 5px;
        margin-bottom: 15px;
        font-weight: bold;
    }
    .columns {
        column-count: 3;
        column-gap: 25px;
        column-rule: 1px solid #999;
        text-align: justify;
    }
    h3 {
        text-align: center;
        margin-top: 20px;
        margin-bottom: 5px;
        break-after: avoid;
    }
    h4 {
        text-align: center;
        margin-top: 15px;
        margin-bottom: 5px;
        break-after: avoid;
    }
    p {
        margin: 0 0 8px 0;
    }
    .indent {
        text-indent: 15px;
    }
    table {
        width: 100%;
        border-collapse: collapse;
        margin: 10px 0;
        break-inside: avoid;
    }
    table td {
        padding: 1px 3px;
        vertical-align: top;
    }
    table td.num {
        text-align: right;
        white-space: nowrap;
    }
    .center {
        text-align: center;
    }
    .small-caps {
        font-variant: small-caps;
    }
    .section-title {
        text-align: center;
        font-weight: bold;
        margin: 15px 0 5px 0;
    }
